    @staticmethod
    def _collect_text(element: marko.element.Element) -> str:
        """Recursively collect the plain text contained in a marko element."""
        children = getattr(element, "children", None)
        if isinstance(children, str):
            return children
        if isinstance(children, list):
            return "".join(
                MarkdownDocumentBackend._collect_text(child) for child in children
            )
        return ""

    @staticmethod
    def _match_custom_tag(
        element: marko.element.Element,
    ) -> Optional[tuple[str, str]]:
        """Detect a ``<signature>``/``<stamp>`` block.

        Marko parses these custom tags as inline HTML wrapped in a paragraph, i.e.
        an opening ``InlineHTML`` node, the inner content, and a closing
        ``InlineHTML`` node. When such a pattern is found, return the (lowercased)
        tag name and the enclosed text content; otherwise return ``None``.
        """
        children = getattr(element, "children", None)
        if not isinstance(children, list) or len(children) < 2:
            return None

        first, last = children[0], children[-1]
        if not (
            isinstance(first, marko.inline.InlineHTML)
            and isinstance(last, marko.inline.InlineHTML)
        ):
            return None

        open_match = _CUSTOM_TAG_OPEN_RE.match(str(first.children).strip())
        close_match = _CUSTOM_TAG_CLOSE_RE.match(str(last.children).strip())
        if open_match is None or close_match is None:
            return None

        tag = open_match.group("tag").lower()
        if close_match.group("tag").lower() != tag:
            return None

        inner_text = "".join(
            MarkdownDocumentBackend._collect_text(child) for child in children[1:-1]
        ).strip()
        return tag, inner_text

